wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(60054941549900002)
,p_plug_name=>'Metrics'
,p_region_css_classes=>'refreshOnLockChange'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--styleA'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(60715562848540251)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'   title',
'  ,null as subtitle',
'  ,val',
'  ,''u-danger'' as class',
'  ,url',
'from',
'  (',
'  select ',
'     1 as seq',
'    ,''Apps with no AuthZ'' as title',
'    ,''Applications without an AuthZ scheme specified can be accessed by any valid user'' as subtitle',
'    ,''f?p=&APP_ID.:1:&APP_SESSION.::::P1_AUTHZ:None'' as url',
'    ,count(*) as val',
'  from ',
'    apex_applications ',
'  where ',
'    authorization_scheme is null ',
'    and application_id not between 4000 and 8999',
'',
'  union',
'',
'  select ',
'     2 as seq',
'    ,''Unevalauted Apps'' as title',
'    ,''Applications that has not been evaluated by SERT'' as subtitle',
'    ,''f?p=&APP_ID.:1:&APP_SESSION.::::P1_EVAL_STATUS:No'' as url',
'    ,count(*) as val',
'  from ',
'    apex_applications ',
'  where ',
'    authentication_scheme != ''SSO'' ',
'    and application_id not between 4000 and 8999',
'--  select ',
'--     2 as seq',
'--    ,''Apps with bad AuthN'' as title',
'--    ,''Applications using weak AuthN schemes have weak overall identity mangement'' as subtitle',
'--    ,''f?p=&APP_ID.:1:&APP_SESSION.:SET_AUTHN:::P1_AUTHENTICATION_SCHEME_TYPE:Custom|No Authentication'' as url',
'--    ,count(*) as val',
'--  from ',
'--    apex_applications ',
'--  where ',
'--    authentication_scheme != ''SSO'' ',
'--    and application_id not between 4000 and 8999',
'',
'  union',
'',
'  select ',
'     3 as seq',
'    ,''Locked Applications'' as title',
'    ,''Applications that are locked and inaccessible'' as subtitle',
'    ,''f?p=&APP_ID.:1:&APP_SESSION.::::P1_LOCKED:Yes'' as url',
'    ,count(*) as val',
'  from ',
'    apex_applications ',
'  where ',
'    availability_status like ''Unavailable%'' ',
'    and application_id not between 4000 and 8999',
'',
'    union',
'',
'  select ',
'     4 as seq',
'    ,''Locked Accounts'' as title',
'    ,''Number of locked user accounts'' as subtitle',
'    ,''f?p=&APP_ID.:5:&APP_SESSION.'' as url',
'    ,count(*) as val',
'  from ',
'    APEX_WORKSPACE_apex_users ',
'  where ',
'    account_locked = ''Yes''',
'',
'  union',
'',
'  select ',
'     5 as seq',
'    ,''Invalid Logins'' as title',
'    ,''Number of invalid login attempts by developers'' as subtitle',
'    ,''f?p=&APP_ID.:5:&APP_SESSION.'' as url',
'    ,count(*) as val',
'  from ',
'    APEX_WORKSPACE_access_log',
'  where',
'    authentication_result = ''AUTH_UNKNOWN_USER''',
'',
'/*',
'  select ',
'     4 as seq',
'    ,''Stuck Emails'' as title',
'    ,''Emails that cannot be sent out'' as subtitle',
'    ,''f?p=&APP_ID.:5:&APP_SESSION.'' as url',
'    ,count(*) as val',
'  from ',
'    apex_mail_queue ',
'  where ',
'    mail_send_count > 0',
'',
'  union',
'',
'  select ',
'     5 as seq',
'    ,''Errors'' as title',
'    ,''Number of errors across all applications'' as subtitle',
'    ,''f?p=&APP_ID.:5:&APP_SESSION.'' as url',
'    ,count(*) as val',
'  from ',
'    apex_workspace_activity_log ',
'  where ',
'    error_message is not null',
'    and application_id not between 4000 and 8999',
'*/',
'  )',
'order by',
'  seq '))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
