,p_region_template_options=>'#DEFAULT#:t-ContentBlock--h2:margin-top-md'
,p_plug_template=>wwv_flow_imp.id(60737191892540262)
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'BELOW'
,p_plug_source_type=>'NATIVE_SMART_FILTERS'
,p_filtered_region_id=>wwv_flow_imp.id(60055100619900004)
,p_attribute_02=>'N'
,p_attribute_03=>'10000'
,p_attribute_04=>'N'
