wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(60055100619900004)
,p_plug_name=>'All Evaluations Report'
,p_parent_plug_id=>wwv_flow_imp.id(60056349210900016)
,p_region_css_classes=>'refreshOnLockChange'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(60709877856540249)
,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with ',
'   a as (select * from apex_applications where application_id not between 4000 and 8999)',
'  ,e as (select * from evals where rule_set_id = (select rule_set_id from rule_sets where rule_set_key = ''INTERNAL''))',
'  ,low_score  as (select pref_value as val from prefs where pref_key = ''LOW_SCORE_VALUE'')',
'  ,high_score as (select pref_value as val from prefs where pref_key = ''HIGH_SCORE_VALUE'')',
'select ',
'   to_char(a.application_id) as application_id',
'  ,a.application_name',
'  ,a.availability_status',
'  ,case when a.authorization_scheme is null then ''None'' else null end as authz',
'  ,case when a.authorization_scheme is null then ''danger'' else null end as authz_class',
'  ,a.authentication_scheme_type',
'  ,case ',
'     when a.availability_status in ',
'       (',
'        ''Available with Developer Toolbar''',
'       ,''Available''',
'       ) then ''success'' ',
'     when a.availability_status in ',
'       (',
'        ''Available to Developers Only''',
'       ,''Restricted Access''',
'       ) then ''warning''',
'     else ''danger'' end as availability_status_class ',
'  ,a.workspace',
'  ,a.created_by',
'  ,a.workspace_id as target_workspace_id',
'  ,a.last_updated_on',
'  ,nvl(e.score, 0) as score',
'  ,case when e.eval_on_date is null then ''Never Evaluated'' else ''Evaluated '' || apex_util.get_since(e.eval_on_date) end as eval_on_date',
'  ,case when e.eval_on_date is null then ''No'' else ''Yes'' end as eval_status',
'  ,case',
'    when e.score < low_score.val then ''danger''',
'    when e.score between low_score.val and high_score.val then ''warning''',
'    when e.score > high_score.val then ''success''',
'    else null',
'   end as score_class',
'  ,case ',
'    when a.availability_status in',
'      (',
'        ''Available with Developer Toolbar''',
'       ,''Available''',
'       ,''Available to Developers Only''',
'       ,''Restricted Access''',
'      )',
'    then ''Lock''',
'    else ''Unlock''',
'   end as change_status',
'  ,case ',
'    when a.availability_status in',
'      (',
'        ''Available with Developer Toolbar''',
'       ,''Available''',
'       ,''Available to Developers Only''',
'       ,''Restricted Access''',
'      )',
'    then ''lock''',
'    else ''unlock''',
'   end as change_status_icon',
'  ,case ',
'    when a.availability_status in',
'      (',
'        ''Available with Developer Toolbar''',
'       ,''Available''',
'       ,''Available to Developers Only''',
'       ,''Restricted Access''',
'      )',
'    then ''No''',
'    else ''Yes''',
'   end as locked',
'  ,case ',
'    when a.availability_status in',
'      (',
'        ''Available with Developer Toolbar''',
'       ,''Available''',
'       ,''Available to Developers Only''',
'       ,''Restricted Access''',
'      )',
'    then ''unlock''',
'    else ''lock''',
'   end as availability_status_icon',
'  ,to_number(count(al.view_date)) as page_views',
'from ',
'   apex_workspace_activity_log al',
'  ,a',
'  ,e',
'  ,low_score',
'  ,high_score',
'where ',
'  a.application_id = al.application_id(+)',
'  and a.application_id = e.application_id(+)',
'group by ',
'   a.application_id ',
'  ,a.application_name',
'  ,a.authorization_scheme',
'  ,a.authentication_scheme_type',
'  ,a.availability_status',
'  ,a.workspace',
'  ,a.created_by',
'  ,a.workspace_id',
'  ,a.last_updated_on',
'  ,e.score',
'  ,e.eval_on_date',
'  ,high_score.val',
'  ,low_score.val',
'order by',
'  workspace',
'  ,application_id'))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$CONTENT_ROW'
,p_plug_query_num_rows=>25
,p_plug_query_num_rows_type=>'SCROLL'
