wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(67729679022620919)
,p_name=>'All Evaluations Report'
,p_parent_plug_id=>wwv_flow_imp.id(60056349210900016)
,p_template=>wwv_flow_imp.id(60708400499540249)
,p_display_sequence=>50
,p_region_css_classes=>'refreshOnLockChange'
,p_region_template_options=>'#DEFAULT#:margin-top-md'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--staticRowColors:t-Report--rowHighlightOff:t-Report--horizontalBorders'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with ',
'   a as (select * from apex_applications where application_id not between 4000 and 8999)',
'  ,e as (select * from evals where rule_set_id = (select rule_set_id from rule_sets where rule_set_key = ''INTERNAL''))',
'select ',
'   a.application_id',
'  ,a.application_name',
'  ,a.availability_status',
'  ,case when a.authorization_scheme is null then ''None'' else null end as authz',
'  ,case when a.authorization_scheme is null then ''danger'' else null end as authz_class',
'  ,a.authentication_scheme_type',
'  ,case ',
'     when a.availability_status in ',
'       (',
'        ''Available with Developer Toolbar''',
'       ,''Available''',
'       ) then ''success'' ',
'     when a.availability_status in ',
'       (',
'        ''Available to Developers Only''',
'       ,''Restricted Access''',
'       ) then ''warning''',
'     else ''danger'' end as availability_status_class ',
'  ,a.workspace',
'  ,a.created_by',
'  ,a.workspace_id',
'  ,a.last_updated_on',
'  ,e.score',
'  ,e.eval_on_date',
'  ,case',
'    when e.score < 50 then ''danger''',
'    when e.score between 50 and 90 then ''warning''',
'    else ''success''',
'   end as score_class',
'  ,case ',
'    when a.availability_status in',
'      (',
'        ''Available with Developer Toolbar''',
'       ,''Available''',
'       ,''Available to Developers Only''',
'       ,''Restricted Access''',
'      )',
'    then ''lock''',
'    else ''unlock''',
'   end as change_status',
'  ,case ',
'    when a.availability_status in',
'      (',
'        ''Available with Developer Toolbar''',
'       ,''Available''',
'       ,''Available to Developers Only''',
'       ,''Restricted Access''',
'      )',
'    then ''lock''',
'    else ''unlock''',
'   end as availability_status_icon',
'  ,count(al.view_date) as page_views',
'  ,null as run_sert',
'  ,null as workspace_users',
'  ,null as application_info',
'from ',
'   apex_workspace_activity_log al',
'  ,a',
'  ,e',
'where ',
'  a.application_id = al.application_id(+)',
'  and a.application_id = e.application_id(+)',
'group by ',
'   a.application_id ',
'  ,a.application_name',
'  ,a.authorization_scheme',
'  ,a.authentication_scheme_type',
'  ,a.availability_status',
'  ,a.workspace',
'  ,a.created_by',
'  ,a.workspace_id',
'  ,a.last_updated_on',
'  ,e.score',
'  ,e.eval_on_date',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(60801687258540290)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_break_cols=>'1:2'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_break_type_flag=>'DEFAULT_BREAK_FORMATTING'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_required_patch=>wwv_flow_imp.id(60671148370540210)
);
