'select',
'  application_id',
'  ,trunc(view_date) as d',
'  ,count(trunc(view_date)) as v ',
'from',
'  apex_workspace_activity_log',
'where',
'  application_id not between 4000 and 8999',
'group by',
'  application_id',
'  ,trunc(view_date)',
'order by',
'  view_date',
')',
'select',
'  application_id',
'  ,''['' || listagg(v, '','') || '']'' as views_by_day',
'from',
'  spark',
'group by',
