'select ',
'   a.authentication_scheme_type',
'  ,a.availability_status',
'  ,a.build_status',
'  ,nvl(a.authorization_scheme,''- None -'') as authorization_scheme',
'  ,a.created_by',
'  ,a.created_on',
'  ,case ',
'     when a.availability_status in ',
'       (',
'        ''Available with Developer Toolbar''',
'       ,''Available''',
'       ) then ''success'' ',
'     when a.availability_status in ',
'       (',
'        ''Available to Developers Only''',
'       ,''Restricted Access''',
'       ) then ''warning''',
'     else ''danger'' end as availability_status_class ',
'from ',
'  apex_applications a',
'where ',
'  a.application_id = :P10_APPLICATION_ID'))
