,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Lock Workspace'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- set the current workspace',
'for x in (select * from apex_workspaces where workspace_id = :P20_WORKSPACE_ID)',
'loop',
'',
'  apex_util.set_workspace(x.workspace);',
'',
'  for y in (select * from apex_applications where workspace_id = x.workspace_id)',
'  loop',
'    -- lock all applications',
'    apex_application_admin.set_application_status ',
'      (',
'       p_application_id     => y.application_id',
'      ,p_application_status => apex_application_admin.c_app_unavailable',
'      ,p_message            => ''x''',
'      );',
'  ',
'    -- lock all accounts',
'    for z in (select * from apex_workspace_apex_users where workspace_id = x.workspace_id)',
'    loop',
'      apex_util.lock_account(p_user_name => z.user_name);',
'    end loop;',
'  end loop;',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(61050521920395108)
